  (97, 'Domlur Club Kitchen', 'South Indian, North Indian, Chinese', 25, 'Domlur 2nd Stage, Near EGL', 1, 4.3, 1, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d', 12.962, 77.64, 'Bengaluru', 'Karnataka', '560071', '+91 80 2535 3344', 'Classic multi-cuisine family diner serving South Indian tiffins, chili chicken, butter naan, and biryani.', 'Domlur', 210, 30, 100, 1, '07:30 AM', '10:30 PM'),
  (98, 'Kabab Magic - Basavanagudi', 'Mughlai, Fast Food, North Indian', 25, 'RV Road, Minerva Circle, Basavanagudi', 1, 4.6, 1, 'https://images.unsplash.com/photo-1544025162-d76694265947', 12.949, 77.575, 'Bengaluru', 'Karnataka', '560004', '+91 80 2661 2233', 'Legendary Bengaluru kebab brand famous for juicy Grilled Chicken, Chicken Shawarma roll, and Mutton Seekh.', 'Basavanagudi', 640, 25, 100, 1, '12:00 PM', '11:00 PM'),
  (99, 'Goli Vada Pav No. 1', 'Street Food, Fast Food, Snacks', 15, 'Commercial Street, Tasker Town', 1, 4.5, 1, 'https://images.unsplash.com/photo-1601050690597-df0568f70950', 12.982, 77.608, 'Bengaluru', 'Karnataka', '560001', '+91 80 2559 1122', 'Indian burger staple serving spicy classic Vada Pav, Schezwan Vada Pav, Cheese Vada Pav, and Masala Fries.', 'Shivajinagar', 340, 25, 100, 1, '10:00 AM', '10:00 PM'),
  (100, 'Hotel Fanoos - Johnson Market', 'Mughlai, Kebabs, Rolls', 25, 'Johnson Market, Hosur Road, Richmond Town', 1, 4.7, 1, 'https://images.unsplash.com/photo-1544025162-d76694265947', 12.961, 77.609, 'Bengaluru', 'Karnataka', '560025', '+91 80 2221 1445', 'Iconic roll joint famous for monster Jumbo Beef/Mutton Sheekh roll, Chicken Shawarma, and crispy parottas.', 'Richmond Road', 710, 25, 100, 1, '12:00 PM', '11:30 PM'),
  (101, 'Suryawanshi - Maharashtrian', 'Maharashtrian, North Indian, Seafood', 35, 'Whitefield Main Road & Indiranagar', 1, 4.6, 1, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d', 12.975, 77.73, 'Bengaluru', 'Karnataka', '560066', '+91 80 4110 3300', 'Spicy Kolhapuri mutton thali, Misal Pav, Puran Poli, Kothimbir Vadi, and Kokum Sharbat.', 'Whitefield', 320, 35, 100, 1, '11:30 AM', '11:00 PM'),
  (102, 'Mezzeh Mediterranean Kitchen', 'Mediterranean, Arabian, Healthy', 30, '100 Feet Road, Indiranagar', 1, 4.7, 1, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47', 12.9755, 77.641, 'Bengaluru', 'Karnataka', '560038', '+91 80 4155 7788', 'Fresh Hummus Falafel platters, Fattoush salad, Chicken Shish Taouk, and freshly baked pita bread.', 'Indiranagar', 280, 35, 100, 1, '12:00 PM', '10:30 PM'),
  (103, 'Madurai Idly Shop - Indiranagar', 'South Indian, Breakfast, Pure Veg', 15, '100 Feet Road, Indiranagar', 1, 4.5, 1, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc', 12.972, 77.642, 'Bengaluru', 'Karnataka', '560038', '+91 80 4125 6677', 'Tamil-style soft mallipoo idlis with 4 varieties of fresh chutneys, podi dosas, and filter coffee.', 'Indiranagar', 410, 25, 100, 1, '06:00 AM', '11:00 PM'),
  (104, 'Leon\'s Burgers & Wings', 'Burgers, Fast Food, American', 25, 'Koramangala 5th Block & Indiranagar', 1, 4.6, 1, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd', 12.934, 77.615, 'Bengaluru', 'Karnataka', '560034', '+91 80 4123 9900', 'Crispy fried chicken burgers, peri peri crinkle fries, hot buffalo wings, and creamy thickshakes.', 'Koramangala', 680, 30, 100, 1, '11:00 AM', '01:00 AM'),
  (105, 'The Filter Coffee - Koramangala', 'South Indian, Breakfast, Pure Veg', 20, '8th Main, 4th Block, Koramangala', 1, 4.8, 1, 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd', 12.9315, 77.624, 'Bengaluru', 'Karnataka', '560034', '+91 80 4099 3322', 'Authentic brass tumbler degree filter coffee paired with mini ghee idlis, onion uttapam, and pineapple kesari.', 'Koramangala', 540, 25, 100, 1, '06:30 AM', '10:30 PM')
