  (1, 1, 'Benne Masala Dosa', 'Crispy golden crepe roasted in pure butter, stuffed with spiced potato mash.', 95, 1, 'https://images.unsplash.com/photo-1610192244261-3f33de3f55e4', '4.9', 1, 'Crispy Dosas', 1, 1, '15 mins'),
  (2, 1, 'Mangalore Bajji (Goli Baje)', 'Crispy golden fried flour fritters served with coconut chutney', 55, 1, 'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600', '4.7', 2, 'Breakfast Specials', 1, 1, '10-15 mins'),
  (3, 1, 'Degree Filter Coffee', 'Traditional chicory blend freshly decocted hot filter coffee', 35, 1, 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600', '4.9', 1, 'Crispy Dosas', 1, 1, '15 mins'),
  (4, 2, 'VB Special Ghee Masala Dosa', 'Signature crispy, thick spongy dosa prepared with aromatic pure ghee', 90, 1, 'https://images.unsplash.com/photo-1610192244261-3f33de3f55e4?w=600', '4.8', 3, 'Crispy Dosas', 1, 1, '15 mins'),
  (5, 2, 'Khara Bath', 'Savory roasted semolina tempered with mustard, curry leaves, and peanuts', 50, 1, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=600', '4.6', 4, 'Breakfast Specials', 1, 1, '10-15 mins'),
  (6, 2, 'Kesari Bath', 'Traditional saffron semolina pudding garnished with roasted cashews and raisins in ghee.', 50, 1, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d', '4.7', 5, 'Snacks & Sweets', 1, 0, '10 mins'),
  (7, 3, 'Original WWII Rava Idli', 'Iconic steamed semolina cake served with potato sagu and hot ghee', 70, 1, 'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=600', '4.9', 6, 'Biryani Specials', 0, 1, '20 mins'),
  (8, 3, 'Bisi Bele Bath', 'Spicy Karnataka one-pot rice and toor dal simmered with vegetables', 110, 1, 'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=600', '4.8', 6, 'Biryani Specials', 0, 1, '20 mins'),
  (9, 3, 'Chandrahara', 'Heritage dessert made with sweet mawa syrup on crispy flour pastry', 80, 1, 'https://images.unsplash.com/photo-1563805042-7684c019e1cb?w=600', '4.6', 7, 'Breakfast Specials', 1, 1, '10-15 mins'),
  (10, 4, 'Death By Chocolate (DBC)', 'Warm chocolate cake topped with double scoops of vanilla ice cream, hot chocolate fudge, and roasted peanuts.', 220, 1, 'https://images.unsplash.com/photo-1563805042-7684c019e1cb', '4.9', 8, 'Signature Sundaes', 1, 1, '10 mins'),
  (11, 4, 'Hot Chocolate Fudge (HCF)', 'Twin vanilla scoops topped with slow-simmered dark fudge sauce', 170, 1, 'https://images.unsplash.com/photo-1563805042-7684c019e1cb?w=600', '4.8', 9, 'Crispy Dosas', 1, 1, '15 mins'),
  (12, 4, 'Trilogy Sundae', 'Trio of strawberry, vanilla, and chocolate scoops with chocolate sauce', 190, 1, 'https://images.unsplash.com/photo-1505394033641-40c6ad1178d7?w=600', '4.7', 9, 'Crispy Dosas', 1, 1, '15 mins'),
  (13, 5, 'Mutton Donne Biryani', 'Traditional seeraga samba rice cooked with tender mutton chunks and coriander-mint paste in leaf bowls.', 320, 1, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8', '4.9', 10, 'Biryani Specials', 0, 1, '20 mins'),
  (14, 5, 'Chicken Donne Biryani', 'Military hotel style spicy biryani served hot in authentic dry palm cups', 220, 1, 'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=600', '4.7', 10, 'Biryani Specials', 0, 1, '20 mins'),
  (15, 5, 'Mutton Dry Pepper Chops', 'Tender lamb chops shallow fried with black pepper and curry leaves', 210, 1, 'https://images.unsplash.com/photo-1544025162-d76694265947?w=600', '4.6', 11, 'Beverages', 1, 0, '5 mins'),
