-- Table: user
CREATE TABLE IF NOT EXISTS `user` (
  `user_id` int NOT NULL AUTO_INCREMENT,
  `username` varchar(100) DEFAULT NULL,
  `email` varchar(150) DEFAULT NULL,
  `phone` varchar(20) DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `role` varchar(50) DEFAULT NULL,
  `password_hash` varchar(255) NOT NULL,
  `last_login` datetime DEFAULT NULL,
  `failed_attempts` int NOT NULL DEFAULT '0',
  `locked_until` datetime DEFAULT NULL,
  `password_changed_at` datetime DEFAULT NULL,
  `reset_token` varchar(100) DEFAULT NULL,
  `reset_token_expires` datetime DEFAULT NULL,
  PRIMARY KEY (`user_id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `uq_user_phone` (`phone`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: restaurant
CREATE TABLE IF NOT EXISTS `restaurant` (
  `restaurant_id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(150) DEFAULT NULL,
  `cuisine_type` varchar(100) DEFAULT NULL,
  `delivery_time` int DEFAULT NULL,
  `address` varchar(255) DEFAULT NULL,
  `admin_user_id` int DEFAULT NULL,
  `rating` double DEFAULT NULL,
  `is_active` tinyint(1) DEFAULT NULL,
  `image_path` varchar(500) DEFAULT NULL,
  `latitude` double DEFAULT '12.9716',
  `longitude` double DEFAULT '77.5946',
  `city` varchar(100) DEFAULT 'Bengaluru',
  `state` varchar(100) DEFAULT 'Karnataka',
  `pincode` varchar(20) DEFAULT '560004',
  `phone` varchar(20) DEFAULT '+91 80 2667 7588',
  `description` text,
  `area` varchar(150) DEFAULT 'Bengaluru Central',
  `review_count` int DEFAULT '50',
  `delivery_fee` double DEFAULT '30',
  `minimum_order` double DEFAULT '100',
  `is_open` tinyint(1) DEFAULT '1',
  `opening_time` varchar(20) DEFAULT '07:00 AM',
  `closing_time` varchar(20) DEFAULT '11:00 PM',
  PRIMARY KEY (`restaurant_id`),
  KEY `admin_user_id` (`admin_user_id`),
  CONSTRAINT `restaurant_ibfk_1` FOREIGN KEY (`admin_user_id`) REFERENCES `user` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: menu_category
CREATE TABLE IF NOT EXISTS `menu_category` (
  `category_id` int NOT NULL AUTO_INCREMENT,
